:root {
  --red: #E0222B;
  --ink: #0B0B0C;
  --white: #FFFFFF;
  --display: "Bebas Neue", sans-serif;
  --text: "Inter", sans-serif;
  --margin: 90px;
}
#stage { font-family: var(--text); color: var(--white); }

/* Slabs: solid blocks of the show's red (or ink) that carry every title. */
.slab {
  position: absolute; display: block; overflow: hidden; white-space: nowrap;
  font-family: var(--display); line-height: 1; letter-spacing: 0.005em;
  padding: 0.13em 0.2em 0.02em; color: var(--white);
}
.slab.red { background: var(--red); }
.slab.ink { background: var(--ink); }
.slab > span { display: inline-block; will-change: transform; }

/* Subtitles: one phrase at a time, bottom-anchored just above the platform UI. */
.scrim {
  position: absolute; left: 0; right: 0; bottom: 0; height: 820px; opacity: 0;
  background: linear-gradient(to bottom, rgba(0,0,0,0) 0%, rgba(0,0,0,0.22) 45%, rgba(0,0,0,0.38) 100%);
}
.cap {
  position: absolute; left: var(--margin); right: var(--margin); bottom: 500px;
  text-align: center; text-wrap: balance;
  font: 800 66px/1.1 var(--text); letter-spacing: -0.015em;
  text-shadow: 0 3px 18px rgba(0,0,0,0.55), 0 1px 3px rgba(0,0,0,0.4);
  opacity: 0;
}
.cap .key { position: relative; display: inline-block; padding: 0 0.12em; margin: 0 0.02em; text-shadow: none; }
.cap .key .bar { position: absolute; left: 0; right: 0; top: 0.06em; bottom: 0.02em; background: var(--red); transform-origin: 0 50%; }
.cap .key .kt { position: relative; }

/* Character files: on each freeze, the lower half darkens and the file builds up. */
.dim {
  position: absolute; inset: 0; opacity: 0;
  background: linear-gradient(to bottom, rgba(8,8,10,0) 34%, rgba(8,8,10,0.6) 56%, rgba(8,8,10,0.86) 100%);
}
.file { position: absolute; left: var(--margin); width: 900px; top: 0; height: 1920px; }
.file .label {
  position: absolute; left: 0; font: 700 30px/1 var(--text); letter-spacing: 0.22em; text-transform: uppercase;
  color: rgba(255,255,255,0.82); white-space: nowrap;
}
.file .label i { display: inline-block; width: 34px; height: 6px; background: var(--red); vertical-align: middle; margin: -4px 18px 0 0; }
.file .label b { color: var(--white); font-weight: 800; }
.file .name { position: absolute; left: -0.02em; overflow: hidden; font-family: var(--display); line-height: 0.86; white-space: nowrap; padding-top: 0.04em; }
.file .name span { display: inline-block; }
.file .role { font-family: var(--text); font-weight: 800; font-size: 34px; letter-spacing: 0.04em; text-transform: uppercase; padding: 12px 20px 10px; }
.file .stats { position: absolute; left: 0; width: 840px; display: flex; gap: 32px; }
.file .stat { flex: 1; }
.file .track { height: 6px; background: rgba(255,255,255,0.2); position: relative; }
.file .fill { position: absolute; left: 0; top: 0; bottom: 0; background: var(--white); transform-origin: 0 50%; }
.file .fill.low { background: var(--red); }
.file .val { font: 400 92px/1 var(--display); margin-top: 16px; }
.file .val.low { color: var(--red); }
.file .what { font: 700 30px/1.05 var(--text); letter-spacing: 0.08em; text-transform: uppercase; color: rgba(255,255,255,0.8); margin-top: 4px; white-space: nowrap; }

