const D = window.DATA;
const { clamp, span, expoOut, easeIn, easeOut, easeInOut } = M;
const stage = document.getElementById("stage");
const el = (tag, cls, parent = stage, text) => {
  const e = document.createElement(tag);
  if (cls) e.className = cls;
  if (text != null) e.textContent = text;
  parent.appendChild(e);
  return e;
};
const FPS = D.fps;
const onFrame = (t) => Math.round(t * FPS) / FPS;

// ---- Timeline ------------------------------------------------------------
const FILES = [
  { a: 13.45, b: 15.87, n: "01", who: "Jillian", name: "MI6", role: "The face of the company", stats: [["Networking", 100], ["Fancy", 99], ["Stairs taken", 0]] },
  { a: 25.08, b: 27.57, n: "02", who: "Aimen", name: "JOYBOY", role: "CEO & plan maker", stats: [["Vision", 100], ["Plans", 99], ["Realism", 7]] },
  { a: 38.98, b: 41.47, n: "03", who: "Rassim", name: "GHOST", role: "CMO, the ads guy", stats: [["Ads", 97], ["PC time", 100], ["Motivation", 12]] },
];
const END = { a: 51.95, b: D.length + 1, label: ["Next", "on The Boyz"], name: "EPISODE 2", role: "Tomorrow" };
const HOOK = { a: 0, b: 3.18, lines: [["BUILDING A", "ink", 64], ["BILLION-DOLLAR", "red", 166], ["COMPANY", "ink", 96]] };
const LABEL = { a: 5.15, b: 6.93, text: "EPISODE 01" };
const HEROES = [
  { a: 11.3, b: 13.2, text: "FANCY", size: 146, top: 224 },
  { a: 21.1, b: 22.9, text: "UNICORN" },
  { a: 42.74, b: 44.54, text: "CASH" },
];
const KEYS = new Set(["mi6", "joyboy", "ghost", "rassim", "billion-dollar", "insane", "impossible", "ground"]);

// Subtitles that start under a character file wait for it to leave; a line left too
// short to read joins the next one.
const lines = [];
for (const s of D.subtitles) {
  const file = FILES.find((f) => s.start >= f.a - 0.05 && s.start < f.b);
  lines.push({ text: s.text, start: file ? file.b + 0.04 : s.start, end: s.end, moved: !!file });
}
for (let i = 0; i < lines.length - 1; i++) {
  const l = lines[i];
  const words = l.text.split(/\s+/).length;
  if (l.moved && l.end - l.start < 0.4 + 0.25 * words && Math.abs(lines[i + 1].start - l.end) < 0.15) {
    lines[i + 1] = { text: `${l.text} ${lines[i + 1].text}`, start: l.start, end: lines[i + 1].end };
    lines.splice(i, 1);
    i--;
  }
}

// ---- Building blocks -----------------------------------------------------
// A slab: wipes in left to right while its text rises into it, and wipes out the same way.
function makeSlab(text, tone, size, parent = stage) {
  const s = el("div", `slab ${tone}`, parent);
  s.style.fontSize = `${size}px`;
  const inner = el("span", null, s, text);
  return { s, inner };
}
function playSlab(o, t, a, b, rise = true) {
  const on = t >= a && t < b;
  o.s.style.display = on ? "block" : "none";
  if (!on) return;
  const pin = expoOut(span(t, a, a + 0.42));
  const pout = easeIn(span(t, b - 0.24, b));
  o.s.style.clipPath = `inset(0 ${((1 - pin) * 100).toFixed(2)}% 0 ${(pout * 100).toFixed(2)}%)`;
  if (rise) o.inner.style.transform = `translateY(${((1 - expoOut(span(t, a + 0.05, a + 0.5))) * 105).toFixed(2)}%)`;
}

let scrim;
const caps = [];
const slabs = [];
const files = [];

window.init = async () => {
  await Promise.all([document.fonts.load('400 100px "Bebas Neue"'), document.fonts.load('800 62px "Inter"'), document.fonts.load('700 30px "Inter"')]);
  const W = D.W;

  // Hook: a stacked title over the elevator, left on the margin.
  let y = 236;
  HOOK.lines.forEach(([text, tone, size], i) => {
    const o = makeSlab(text, tone, size);
    if (o.s.offsetWidth > 900) o.s.style.fontSize = `${(size * 900) / o.s.offsetWidth}px`;
    o.s.style.left = "90px";
    o.s.style.top = `${y}px`;
    y += o.s.offsetHeight + 8;
    slabs.push({ o, a: HOOK.a + i * 0.08, b: HOOK.b - (HOOK.lines.length - 1 - i) * 0.05 });
  });

  // The episode label, under the show's logo in the intro sting.
  {
    const o = makeSlab(LABEL.text, "red", 64);
    o.s.style.left = "168px";
    o.s.style.top = "812px";
    slabs.push({ o, a: LABEL.a, b: LABEL.b });
  }

  // Hero words: one red slab, centred above the head.
  for (const h of HEROES) {
    const o = makeSlab(h.text, "red", h.size ?? 170);
    o.s.style.left = `${(W - o.s.offsetWidth) / 2}px`;
    o.s.style.top = `${h.top ?? 236}px`;
    slabs.push({ o, a: h.a, b: h.b });
  }

  // Subtitles.
  scrim = el("div", "scrim");
  for (const l of lines) {
    const c = el("div", "cap");
    let keyed = null;
    l.text.split(/\s+/).forEach((w, i) => {
      if (i) c.appendChild(document.createTextNode(" "));
      if (!keyed && KEYS.has(w.toLowerCase().replace(/[^a-z0-9-]/g, ""))) {
        const k = el("span", "key", c);
        const bar = el("i", "bar", k);
        el("span", "kt", k, w);
        keyed = bar;
      } else c.appendChild(document.createTextNode(w));
    });
    caps.push({ c, bar: keyed, ...l });
  }

  // Character files (and the end card, built the same way).
  for (const f of [...FILES, END]) {
    const dim = el("div", "dim");
    const box = el("div", "file");
    const isEnd = f === END;
    const Y = isEnd ? { label: 1112, name: 1152, role: 1352 } : { label: 944, name: 984, role: 1194, stats: 1276 };
    const label = el("div", "label", box);
    label.innerHTML = `<i></i><b>${isEnd ? f.label[0] : f.n}</b>&nbsp;&nbsp;${isEnd ? f.label[1] : f.who}`;
    label.style.top = `${Y.label}px`;
    const name = el("div", "name", box);
    name.style.top = `${Y.name}px`;
    name.style.fontSize = "228px";
    const letters = [...f.name].map((ch) => el("span", null, name, ch === " " ? " " : ch));
    const role = makeSlab(f.role.toUpperCase(), "red", 34, box);
    role.s.classList.add("role");
    role.s.style.left = "0px";
    role.s.style.top = `${Y.role}px`;
    const stats = [];
    if (f.stats) {
      const row = el("div", "stats", box);
      row.style.top = `${Y.stats}px`;
      for (const [what, v] of f.stats) {
        const col = el("div", "stat", row);
        const track = el("div", "track", col);
        const fill = el("div", `fill${v < 20 ? " low" : ""}`, track);
        const val = el("div", `val${v < 20 ? " low" : ""}`, col, "0");
        const w = el("div", "what", col, what);
        stats.push({ fill, val, w, v });
      }
    }
    files.push({ f, dim, box, label, letters, role, stats });
  }
};

window.render = (t) => {
  // Slabs.
  for (const { o, a, b } of slabs) playSlab(o, t, a, b);

  // Character files.
  let dimmed = 0;
  for (const { f, dim, box, label, letters, role, stats } of files) {
    const on = t >= f.a && t < f.b;
    box.style.display = dim.style.display = on ? "block" : "none";
    if (!on) continue;
    const d = easeOut(span(t, f.a, f.a + 0.22)) * (1 - easeIn(span(t, f.b - 0.22, f.b)));
    dim.style.opacity = d.toFixed(3);
    dimmed = Math.max(dimmed, d);
    const out = easeIn(span(t, f.b - 0.26, f.b - 0.02));
    box.style.clipPath = `inset(0 0 0 ${(out * 100).toFixed(2)}%)`;
    const lp = expoOut(span(t, f.a + 0.06, f.a + 0.46));
    label.style.clipPath = `inset(0 ${((1 - lp) * 100).toFixed(2)}% 0 0)`;
    letters.forEach((s, i) => {
      const p = expoOut(span(t, f.a + 0.1 + i * 0.045, f.a + 0.62 + i * 0.045));
      s.style.transform = `translateY(${((1 - p) * 102).toFixed(2)}%)`;
    });
    playSlab(role, t, f.a + 0.3, f.b + 1);
    const tq = onFrame(t);
    stats.forEach((s, i) => {
      const a = f.a + 0.55 + i * 0.12;
      const p = easeInOut(span(tq, a + 0.1, a + 0.8));
      s.fill.style.transform = `scaleX(${((p * s.v) / 100).toFixed(4)})`;
      s.val.textContent = String(Math.round(p * s.v));
      const e = expoOut(span(t, a, a + 0.4));
      for (const n of [s.val, s.w]) {
        n.style.opacity = e.toFixed(3);
        n.style.transform = `translateY(${((1 - e) * 14).toFixed(2)}px)`;
      }
      s.fill.parentElement.style.opacity = e.toFixed(3);
    });
  }

  // Subtitles and the soft scrim behind them.
  let shade = 0;
  for (const c of caps) {
    shade = Math.max(shade, span(t, c.start - 0.2, c.start) * (1 - span(t, c.end, c.end + 0.25)));
    const on = t >= c.start && t < c.end;
    c.c.style.visibility = on ? "visible" : "hidden";
    if (!on) continue;
    const e = expoOut(span(t, c.start, c.start + 0.32));
    c.c.style.opacity = (span(t, c.start, c.start + 0.07) * (1 - span(t, c.end - 0.06, c.end))).toFixed(3);
    c.c.style.transform = `translateY(${((1 - e) * 16).toFixed(2)}px)`;
    if (c.bar) c.bar.style.transform = `scaleX(${expoOut(span(t, c.start + 0.08, c.start + 0.4)).toFixed(4)})`;
  }
  scrim.style.opacity = (shade * (1 - dimmed)).toFixed(3);
};
